D[941]={"^Increases your total health by (.-)%%%.\n\nIncreases the health of your tamed beast, enslaved demon, dominated undead, tamed dragonkin, and tethered elemental by (.-)%%%.%s*$","Aumenta sua vida total em {{1}}%.\n\nAumenta a vida de sua fera domada, demônio escravizado, não-morto dominado, dracônico domado elemental atado em {{2}}%."}
D[1208]={"^Increases the damage dealt by Sinister Strike, Backstab and Shiv by (.-)%%%.\n\nShiv and Grappling Hook Follow%-Up have a 50%% chance to Daze the target for (.-)%.%s*$","Aumenta em {{1}}% o dano causado por Golpe Sinistro, Punhalada e Estocada.\n\nEstocada e Seguimento do Gancho têm 50% de chance de Atordoar o alvo por {{2}}."}
D[1209]={"^Increases the damage dealt by Sinister Strike, Backstab and Shiv by (.-)%%, and your Shiv and Grappling Hook Follow%-Up has a 100%% chance to Daze the target for (.-)%.%s*$","Aumenta em {{1}}% o dano causado por Golpe Sinistro, Punhalada e Estocada. Estocada e Seguimento do Gancho têm 100% de chance de Atordoar o alvo por {{2}}."}
D[2633]={"^|cFF66DDFFLevel 10 Passive|r\nYour |cffffffffWild Strike|r now generates 1 additional |cff8fff7aAdvantage|r%.\n\nRemoves the minimum range of your ranged abilities%.%s*$","|cFF66DDFFPassivo de Nível 10|r\nSeu |cffffffffGolpe Selvagem|r agora gera 1 pontos adicionais de |cff8fff7aVantagem|r.\n\nElimina o grau mínimo de suas habilidades à distância."}
D[2634]={"^|cFF66DDFFLevel 10 Passive|r\nYour damaging critical strikes now spawn a green |cFFFFFFFFDream Flower|r at a random location within 15 yds of you%.Can only occur once per sec%.%s*$","|cFF66DDFFPassivo de Nível 10|r\nSeus acertos críticos que causam dano agora geram uma |cFFFFFFFFFlor do Sonho|r verde em um local aleatório a até 15 m de você. Só pode ocorrer uma vez por segundo."}
D[2635]={"^|cFF66DDFFLevel 50 Passive|r\nYour damaging critical strikes now spawn a green |cFFFFFFFFDream Flower|r at a random location within 15 yds of you%.Can only occur once per sec%.%s*$","|cFF66DDFFPassivo de Nível 50|r\nSeus acertos críticos que causam dano agora geram uma |cFFFFFFFFFlor do Sonho|r verde em um local aleatório a até 15 m de você. Só pode ocorrer uma vez por segundo."}
D[3510]={"^|cFF66DDFFLevel 40 Passive|r\nAllows the periodic damage dealt by |cffffffffSerrated Shot|r to critically strike%.%s*$","|cFF66DDFFPassivo de Nível 40|r\nPermite que o dano periódico causado por |cffffffffDisparo Serrado|r possa ser um acerto crítico."}
D[3511]={"^Reduces the cooldown of |cffffffffFlank|r by (.-) sec and increases its damage by (.-)%%%.%s*$","Reduz a recarga de |cffffffffFlanqueamento|r em {{1}} s. e aumentar seu dano em {{2}}%."}
D[3512]={"^Increases the range of |cffffffffReposition|r by (.-) yds%.%s*$","Aumenta o alcance de |cffffffffRealocar|r em {{1}} m."}
D[3701]={"^|cffffffffAssault|r and |cffffffffWild Strike|r now reduce the enemy's Armor by (.-)%% for (.-), stacking up to (.-) times%.%s*$","|cffffffffAssalto|r e |cffffffffGolpe Selvagem|r agora reduzem a armadura do inimigo em {{1}}% durante {{2}}, acumulando até {{3}} vezes."}
D[3706]={"^Direct Physical damage dealt now has a (.-)%% chance to refresh a |cffffffffSpread Shot|r charge%.%s*$","O dano Físico direto agora tem {{1}}% de chance de recarregar uma |cffffffffDisparo estendido|r."}
D[3832]={"^Your |cffffffffWild Strike|r now generates 1 additional |cff8fff7aAdvantage|r%.\n\nRemoves the minimum range of your ranged abilities%.%s*$","Seu |cffffffffGolpe Selvagem|r agora gera 1 pontos adicionais de |cff8fff7aVantagem|r.\n\nElimina o alcance mínimo de suas habilidades à distância."}
D[3865]={"^Fire at an enemy, inflicting (.-) Physical damage and empowering your next 3 |cffffffffQuick Shots|r to deal (.-)%% increased Damage and generate a bonus stack of |cff8fff7aAdvantage|r%.%s*$","Dispara contra um inimigo, causando {{1}} de dano Físico e fortalecendo seus próximos 3 |cffffffffTiros Rápidos|r para que cause um dano maior em {{2}}% e gere um acúmulo adicional de |cff8fff7aVantagem|r."}
D[3868]={"^Fire a serrated arrow at an enemy, causing them to bleed for (.-) Physical damage, repeating every (.-) sec for (.-)%.\n\nDuration increased by (.-) sec per stack of |cff8fff7aAdvantage|r%.%s*$","Dispara uma flecha serrilhada contra um inimigo, causando hemorragia e fazendo com que sofra {{1}} de dano Físico a cada {{2}} s durante {{3}}.\n\nDuração aumentada em {{4}} s por acúmulo de |cff8fff7aVantagem|r."}
D[3871]={"^|cFFFFFFFF2 Charges|r \n|cffffffff8 sec recharge|r\nFire several arrows, hitting up to (.-) targets for ranged Weapon Damage plus (.-) Physical Damage|r%.\n\nDamage dealt generates 1 |cffffffffArchery Point|r%.%s*$","|cFFFFFFFF2 Cargas|r\n|cffffffff8 s recarga|r\nDispara várias flechas, atingindo até {{1}} alvos por dano da arma à distância mais {{2}} de dano Físico.|r.\n\nO dano causado gera 1 |cffffffffPonto de Arquearia|r."}
