D[76604]={"^Empowers your next damaging ability against the target based on the amount of stacks%.\n\n1 stack %- Silences for (.-)%.\n\n2 stacks %- Applies previous effect and 4 stacks of |cFFFFFFFFDeepwood Poison|r%.\n\n3 stacks %- Applies previous effects and stuns for (.-)%.\n\nLasts (.-) %(8 sec vs players%) and additional applications do not refresh the duration%.%s*$","Potencializa seu próximo habilidade dano contra o alvo conforme a quantidade acúmulos.\n\n1 acúmulo - Silencia durante {{1}}.\n\n2 acúmulos - Aplica o efeito anterior e adiciona 4 acúmulos de |cFFFFFFFFVeneno da Mata Profunda|r.\n\n3 acúmulos - Aplica os efeitos anteriores e atordoa durante {{2}}.\n\nDura {{3}} (8 s contra jogadores) e as aplicações adicionais não atualizam a duração."}
D[76607]={"^Your |cffffffffSkullpiercer|r used with 5 stacks of |cff8fff7aAdvantage|r now extends the duration of |cffffffffDirty Blades|r by (.-) sec%.%s*$","Usar |cffffffffPerfurador de Crânios|r com 5 acúmulos de |cff8fff7aVantagem|r agora prolonga a duração de |cffffffffLâminas Sujas|r em {{1}} s."}
D[76793]={"^|cffffffffHunting Shot|r now causes your next |cffffffffSerrated Shot|r to explode on impact, hitting up to (.-) targets%.\n\nIn addition, when your |cFFFFFFFFSerrated Shot|r deals damage, you generate (.-) Focus%.%s*$","|cffffffffTiro de Caça|r agora faz com que seu próximo |cffffffffDisparo Serrado|r exploda ao impactar, golpeando até {{1}} alvos.\n\nAlém disso, quando seu |cFFFFFFFFDisparo Serrado|r causa dano, gera {{2}} Foco."}
D[76794]={"^|cffffffffHunting Shot|r now causes your next |cffffffffSerrated Shot|r to explode on impact, hitting up to (.-) targets%.\n\nIn addition, when your Serrated Shot deals damage, you generate 5 Focus%. This effect cannot occur more than once per second%.%s*$","|cffffffffTiro de Caça|r agora faz com que seu próximo |cffffffffDisparo Serrado|r exploda ao impactar, golpeando até {{1}} alvos.\n\nAlém disso, quando seu Disparo Serrado causa dano, gera 5 Foco. Este efeito não pode acontecer mais de uma vez por segundo."}
D[76871]={"^|cFF66DDFFLevel 30 Passive|r\nIncreases the damage dealt by your off%-hand weapon by (.-)%%%.%s*$","|cFF66DDFFPassivo de Nível 30|r\nAumenta o dano de sua arma secundária em {{1}}%."}
