T[479]={"^Increases ranged attack power by (.-)%%%.%s*$","Aumenta o poder de ataque à distância em {{1}}%."}
T[504]={"^Reduces the cast time of |cffffffffQuick Shot|r by (.-)%%%.%s*$","Reduz o tempo de lançamento de |cffffffffTiro Rápido|r em {{1}}%."}
T[507]={"^Increases the damage of |cffffffffWild Strike|r, |cffffffffWoodland Arrow|r, |cffffffffAssault|r, and |cffffffffRavage|r by (.-)%%%.%s*$","Aumenta o dano de |cffffffffGolpe Selvagem|r, |cffffffffFlecha Silvestre|r, |cffffffffAssalto|r e |cffffffffDevastar|r em {{1}}%."}
T[525]={"^Healing received reduced by (.-)%%%.%s*$","Reduz a cura recebida em {{1}}%."}
T[567]={"^Causes |cffffffffBackstep|r to allow your next |cffffffffSkullpiercer|r to critically strike%.%s*$","Permite que seu próximo |cffffffffPasso para Trás|r cause um acerto crítico garantido com |cffffffffPerfurador de Crânios|r."}
T[753]={"^Increases the critical strike chance and critical damage of |cffffffffSkullpiercer|r and |cffffffffPrecision Shot|r by (.-)%%%.%s*$","Aumenta em {{1}}% a chance de acerto crítico e o bônus de dano crítico de |cffffffffPerfurador de Crânios|r e |cffffffffDisparo Preciso|r."}
T[754]={"^Reduces the cooldown and shared cooldowns of your |cffffffffQuivers|r by (.-) sec and increases the damage of |cffffffffSkullpiercer|r by (.-)%%%.%s*$","Reduz os tempos de recarga de seus |cffffffffaljavas|r e as compartilhadas em {{1}} s. e aumenta o dano de |cffffffffPerfurador de Crânios|r em {{2}}%."}
T[757]={"^Causes your first |cffffffffWild Strike|r while |cffffffffCounterblades|r is active to stun the target for (.-)%.%s*$","Faz com que seu primeiro |cffffffffGolpe Selvagem|r enquanto |cffffffffContra-ataques|r está ativo te atordoe o alvo durante {{1}}."}
T[763]={"^Causes the |cffffffffRoughed Up|r effect from |cffffffffAdaptation: Bandit|r to increase damage the target takes from |cffffffffBrigand Strike|r and |cffffffffDuelist Strike|r by (.-)%%%.%s*$","O efeito |cffffffffMachucado|r de |cffffffffAdaptação: Bandido|r aumenta em {{1}}% o dano que o alvo recebe de |cffffffffGolpe do Salteador|r e |cffffffffGolpe do Duelista|r."}
T[764]={"^Increases the chance that critical strikes will apply |cffffffffRoughed Up|r while |cffffffffAdaptation: Bandit|r is active by (.-)%%%.%s*$","Aumenta em {{1}}% a chance de acertos críticos aplicarem |cffffffffMachucado|r enquanto |cffffffffAdaptação: Bandido|r estiver ativa."}
T[765]={"^Nature Damage dealt increased by (.-)%%%.%s*$","O dano de Natureza aumenta em {{1}}%."}
T[766]={"^Increases damage you deal to bleeding enemies by (.-)%%%.%s*$","Aumenta seu dano contra inimigos com hemorragia em {{1}}%."}
T[768]={"^Reduces the cooldowns of |cFFFFFFFFFalcon's Call|r and |cFFFFFFFFFalcon Dive|r by (.-)%%%.%s*$","Reduz os tempos de recarga de |cFFFFFFFFChamado do Falcão|r e |cFFFFFFFFMergulho do Falcão|r em {{1}}%."}
T[772]={"^Increases the damage of |cffffffffSkullpiercer|r by (.-)%% and using |cFFFFFFFFSkullpiercer|r increases the effectiveness of your next Horn spell by (.-)%%%.%s*$","Aumenta o dano de |cffffffffPerfurador de Crânios|r em {{1}}% e usar |cFFFFFFFFPerfurador de Crânios|r aumenta a eficácia de seu próximo feitiço de Chifre em {{2}}%."}
T[773]={"^Increases the damage of Falconstrike by (.-)%%, stacking (.-) times%.%s*$","Aumenta o dano de Golpe do Falcão em {{1}}%, acumulando-se {{2}} vezes."}
T[774]={"^Causes |cffffffffFalcon's Dive|r, |cffffffffFalconstrike|r, and |cffffffffFalcon's Call|r to make your next |cffffffffRanger's Horn|r incur no cooldown%.%s*$","Faz com que |cffffffffMergulho do Falcão|r, |cffffffffGolpe do Falcão|r e |cffffffffChamado do Falcão|r façam seu próximo |cffffffffTrompa do Patrulheiro|r não acionar recarga."}
T[780]={"^Reduces the cooldown of |cffffffffGrapplebomb|r by (.-) sec and increases its damage by (.-)%%%.%s*$","Reduz a recarga de |cffffffffGrapplebomb|r em {{1}} s. e aumenta seu dano em {{2}}%."}
T[1202]={"^Causes |cffffffffFlank|r to apply |cffffffffDeepwood Poison|r%.%s*$","Faz com que |cffffffffFlanqueamento|r aplique |cffffffffVeneno da Mata Profunda|r."}
T[1204]={"^Grants (.-)%% increased critical strike chance%. Critical strikes with Wild Strike and Flank have a (.-)%% chance to apply Roughed Up and Counterstruck%.%s*$","Aumenta em {{1}}% sua chance de acerto crítico. Acertos críticos com Golpe Selvagem e Flanqueamento têm {{2}}% de chance de aplicar Machucado e Contra-ataqueado."}
T[1337]={"^Using |cffffffffFlank|r from behind a target increases the damage of your next |cffffffffAssault|r against them by (.-)%% for (.-)%.%s*$","Usar |cffffffffFlanqueamento|r por trás de um alvo aumenta o dano de seu próximo |cffffffffAssalto|r contra eles em {{1}}% durante {{2}}."}
T[1493]={"^Critical strike chance increased by (.-)%%%. Movement speed increased by (.-)%%%.%s*$","Aumenta a chance de acerto crítico em {{1}}%. Aumenta a velocidade de movimento em {{2}}%."}
T[1541]={"^Dealing Physical Damage has a chance to reduce the cast time of your next Ballista Shot by (.-)%%, stacks up to 5 times%.\n\nAlso increases the Critical Strike Damage Bonus of Ballista Shot by (.-)%%%.%s*$","Causar dano Físico tem chance de reduzir em {{1}}% o tempo de lançamento do seu próximo Tiro de Balista, acumulando até 5 vezes.\n\nTambém aumenta em {{2}}% o bônus de dano crítico de Tiro de Balista."}
T[1629]={"^Unable to Mount%. Movement Speed reduced by (.-)%%%.%s*$","Você não pode montar. Sua velocidade de movimento é reduzida em {{1}}%."}
T[1676]={"^Attack Power increased by (.-)%%, Parry Chance increased by (.-)%%%.\n\nSuccessful Parries have a chance to apply Counterstruck%.\n\nEquipping a Ranged Weapon or an Off%-Hand Melee Weapon will disable this Adaptation%.%s*$","Poder de Ataque aumentado em {{1}}% e chance de Aparo aumentada em {{2}}%.\n\nAparos bem-sucedidos têm uma chance de aplicar Contra-ataque.\n\nEquipar uma arma de longo alcance ou uma arma corpo a corpo na mão secundária desativa esta Adaptação."}
T[1788]={"^Increases critical strike chance by (.-)%%, but increases your Maximum Focus by (.-)%% and your Physical Critical Strike Bonus Damage by (.-)%%%.%s*$","Aumenta sua chance de acerto crítico em {{1}}%, mas aumenta seu Máximo Foco em {{2}}% e seu Dano Adicional por Acerto crítico Físico em {{3}}%."}
T[1798]={"^Your |cffffffffBolt|r abilities now grant you a stack of |cffffffffSentry|r for (.-), increasing the critical strike chance of your next |cffffffffRepeater|r by (.-)%%%. Stacks up to (.-) times%.%s*$","Sua habilidade |cffffffffBolt|r agora concedem a você um acúmulo de |cffffffffSentinela|r em {{1}}, aumentando a chance de acerto crítico de seu próximo |cffffffffRepetidora|r em {{2}}%. Acumula até {{3}} vezes."}
T[1836]={"^Attack Speed increased by (.-)%%%.%s*$","Velocidade de ataque aumentada em {{1}}%."}
T[1900]={"^While active, you generate 3 Focus every (.-) sec%.%s*$","Enquanto estiver ativo, gera 3 Enfoque a cada {{1}} s."}
T[1901]={"^Magic Damage increased by (.-)%%%. You do not suffer any pushback from taking damage while casting%.%s*$","Dano mágico aumentado em {{1}}%. Não você sofre nenhum recuo ao receber dano enquanto lança um feitiço."}
T[1902]={"^For (.-), |cffffffffQuick Shots|r generate an additional |cffffffffArchery Point|r and |cffffffffSkullpiercer Shot|r%$%?s806345%[ and |cffffffffWoodland Arrow|r%]%[ deal (.-)%% increased damage%.\n\nFor the duration, |cffffffffSkullpiercer Shots|r%$%?s806345%[ and |cffffffffWoodland Arrow|r%]%[ used with 5 |cffffffffArchery Points|r will summon 1 |cffffffffWar Falcon|r%.%s*$","Durante {{1}}, |cffffffffTiros Rápidos|r geram um |cffffffffPonto de Arquearia|r adicional, e |cffffffffDisparo Perfurador de Crânios|r$?s806345[ e |cffffffffFlecha Silvestre|r][] causam {{2}}% a mais de dano.\n\nDurante esse período, |cffffffffDisparos Perfuradores de Crânios|r$?s806345[ e |cffffffffFlecha Silvestre|r][] usados com 5 |cffffffffPontos de Arquearia|r invocam 1 |cffffffffFalcão de Guerra|r."}
