T[3669]={"^Increases all bonuses that your stacks of |cff8fff7aAdvantage|r provide by (.-)%%%.%s*$","Aumenta todos benefícios que concedem seus acúmulos de |cff8fff7aVantagem|r em {{1}}%."}
