T[9476]={"^Your next Serrated Shot will hit up to (.-) targets%.%s*$","Seu próximo Disparo Serrado afetará até a {{1}} alvos."}
T[9495]={"^Reduce horn cooldowns%s*$","Reduz a recarga dos chifres"}
T[9500]={"^Increases the damage of |cffffffffHunting Shot|r by (.-)%%%.%s*$","Aumenta o dano de |cffffffffTiro de Caça|r em {{1}}%."}
T[9649]={"^You cannot trigger Counterstruck through Adaptation: Brigand%.%s*$","Você não pode ativar Contra-ataqueado através de Adaptação: Salteador."}
T[9699]={"^Serrated Shot can now critically strike%.%s*$","O Tiro Serrado agora pode ser um acerto crítico."}
T[9792]={"^ and increases bonus damage |cFFFFFFFFSerrated Shot|r receives from ranged attack power by (.-)%%%.%s*$","e aumenta o dano adicional que recebe |cFFFFFFFFDisparo Serrado|r do poder de ataque à distância em {{1}}%."}
T[9912]={"^Increases the damage of |cffffffffWild Strike|r and |cffffffffQuick Shot|r by (.-)%%%. Stacks (.-) times%.%s*$","Aumenta o dano de |cffffffffGolpe Selvagem|r e |cffffffffTiro Rápido|r em {{1}}%. Acumula {{2}} vezes."}
T[9997]={"^hiddeen%s*$","Oculto"}
T[10115]={"^Causes your Wild Strike ability to Slow affected targets by (.-)%% for (.-)%.\n\nUsing Quick Shot on an enemy Slowed by this effect consumes it to Root them in place for (.-) and cause (.-) Naure Damage every (.-) sec%.\n\nAlso teaches you Wargstride, and increases all Nature Damage done by (.-)%%%.%s*$","Faz sua habilidade Golpe Selvagem reduzir a velocidade dos alvos afetados em {{1}}% durante {{2}}.\n\nUsar Disparo Rápido em um inimigo desacelerado por este efeito o consome, imobilizando o alvo durante {{3}} e causando {{4}} de dano de Natureza a cada {{5}} s.\n\nTambém ensina Marcha Loba e aumenta todo o dano de Natureza causado em {{6}}%."}
T[10545]={"^Quick shot is enabled, costs (.-)%% less Focus, and deals (.-)%% increased damage%. Each Quick Shot consumes (.-) sec of this effect's Duration%.\n\nUsing Wild Strike ends this effect%.%s*$","Disparo rápido está habilidadeo, custa {{1}}% menos Enfoco e causa dano aumentado em {{2}}%. Cada Disparo Rápido consome {{3}} s da duração deste efeito.\n\nUsar acerto Selvagem termina este efeito."}
T[11006]={"^Your Quick Shot ability fires (.-)%% faster%. Your next Ballista Shot or Skullpiercer causes (.-)%% increased damage%. Stacks (.-) times%.%s*$","Sua habilidade Disparo rápido dispara {{1}}% mais rápido. Seu próximo Disparo de balhista ou Penetracuerpo causa {{2}}% dano adicional. Acumula {{3}} vezes."}
T[11167]={"^Your next Spread Shot has no cost and incurs no cooldown%.%s*$","Seu próximo Disparo Estendido não tem custo e não gera recarga."}
T[11252]={"^Your next Wild Strike deals (.-)%% increased damage and Critically Strikes%.%s*$","Seu próximo acerto Selvagem causa dano aumentado em {{1}}% e realiza acertos críticos."}
T[11259]={"^Increases ranged attack power by (.-)%%, and ranged haste by (.-)%%%. Reduces melee haste by (.-)%%%.\n\nWhenever you use Serrated Shot, Soaring Shot or Precision Shot you have a chance to reset the cooldown of Hail of Arrows%.%s*$","Aumenta o poder de ataque à distância em {{1}}% e a aceleração à distância em {{2}}%. Reduz a aceleração corpo a corpo em {{3}}%.\n\nSempre que usar Disparo Serrado, Disparo Ascendente ou Disparo Preciso, você tem uma chance de reiniciar a recarga de Tempestade de Flechas."}
T[11640]={"^Disguised as a Dark Ranger!%s*$","Disfarçado como um Arquera Sombria!"}
T[11722]={"^Equips your Dark Ranger General's Quiver%.%s*$","Equipa a Aljava do General Patrulheiro Sombrio."}
T[12810]={"^Rank 6: Highwayman\n\nHigh%-risk mode enables FFA PvP and causes you and anyone else you kill to drop loot on death%.\n\nYou gain Glory when defeating enemies within 2 ranks of your own in High%-risk, but also lose Glory on death%.%s*$","Grau 6: Salteador de Estrada\n\nO modo de alto risco habilidade JxJ FFA e Faz com que você e qualquer outra pessoa que mate descartem saque na morte.\n\nGanha Glória ao derrotar a inimigos dentro de 2 graus do seu em Alto Risco, mas também perde Glória na morte."}
T[14059]={"^Fires a cannon shot specifically designed to take down ducks with precision%. Generates 5 Heat%.%s*$","Dispara um tiro de canhão especificamente projetado para derrubar patos com precisão. Gera 5 Calor."}
T[14165]={"^Direct Physical damage dealt now has a (.-)%% chance to refresh a |cffffffffSpread Shot|r charge%.%s*$","O dano Físico direto agora tem {{1}}% de chance de recarregar uma |cffffffffDisparo estendido|r."}
T[14406]={"^Marked%. The ranger has (.-)%% increased Physical critical strike chance against this target%.%s*$","Marcado. O patrulheiro tem {{1}}% de chance aumentada de acerto crítico físico contra este alvo."}
T[14407]={"^For (.-), your next 10 |cffffffffQuick Shots|r generate an additional stack of |cff8fff7aAdvantage|r and |cffffffffSkullpiercer|r and |cffffffffWoodland Arrow|r deal (.-)%% increased damage%.\n\nFor the duration, |cffffffffSkullpiercers|r will summon 1 |cffffffffWar Falcon|r%.%s*$","Durante {{1}}, seus próximos 10 |cffffffffTiros Rápidos|r geram um acúmulo adicional de |cff8fff7aVantagem|r e |cffffffffPerfurador de Crânios|r e |cffffffffFlecha Silvestre|r causam {{2}}% a mais de dano.\n\nDurante o resto do tempo, |cffffffffPerfuracránios|r invocarão 1 |cffffffffFalcão de Guerra|r."}
T[14409]={"^Generates Focus%s*$","Gera Foco."}
T[14452]={"^Gain the ability to craft |cffffffffCrude Leather|r from the Leather obtained from Skinning, gives you a chance to find it when Skinning beasts, and increases your Skinning speed%.\n\nAllows you to craft items that require |cffffffffCrude Leather|r%.%s*$","Permite criar |cffffffffCouro Rústico|r a partir do couro obtido com Esfolamento, concede chance de encontrá-lo ao esfolar feras e aumenta sua velocidade de Esfolamento.\n\nPermite criar itens que exigem |cffffffffCouro Rústico|r."}
T[14498]={"^Haste increased by 15%%%.%s*$","aceleração aumentada em 15%."}
T[14602]={"^|cffffffffRepeater|r enables the use of |cffffffffCollect Bounty|r regardless of the target's health%.%s*$","|cffffffffRepetidora|r habilita o uso de |cffffffffColetar o saque|r independentemente da vida do alvo."}
T[14686]={"^Increases the duration of |cffffffffQuivers|r by (.-) sec%.%s*$","Aumenta a duração de |cffffffffTremores|r em {{1}} s."}
T[14748]={"^Causes |cffffffffFlank|r to apply |cffffffffDeepwood Poison|r%.%s*$","Faz com que |cffffffffFlanqueamento|r aplique |cffffffffVeneno da Mata Profunda|r."}
T[14885]={"^Dealing Physical Damage has a chance to reduce the cast time of your next Ballista Shot by (.-)%%, stacks up to 5 times%.\n\nAlso increases the Critical Strike Damage Bonus of Ballista Shot by (.-)%%%.%s*$","Causar dano Físico tem chance de reduzir em {{1}}% o tempo de lançamento do seu próximo Tiro de Balista, acumulando até 5 vezes.\n\nTambém aumenta em {{2}}% o bônus de dano crítico de Tiro de Balista."}
T[14953]={"^Allows Spread Shot to generate Archery Points%.%s*$","Permite que Disparo Estendido gere Pontos de Arquearias."}
T[15012]={"^While active, you generate 3 Focus every (.-) sec%.%s*$","Enquanto estiver ativo, gera 3 Enfoque a cada {{1}} s."}
T[15013]={"^For (.-), |cffffffffQuick Shots|r generate an additional |cffffffffArchery Point|r and |cffffffffSkullpiercer Shot|r%$%?s806345%[ and |cffffffffWoodland Arrow|r%]%[ deal (.-)%% increased damage%.\n\nFor the duration, |cffffffffSkullpiercer Shots|r%$%?s806345%[ and |cffffffffWoodland Arrow|r%]%[ used with 5 |cffffffffArchery Points|r will summon 1 |cffffffffWar Falcon|r%.%s*$","Durante {{1}}, |cffffffffTiros Rápidos|r geram um |cffffffffPonto de Arquearia|r adicional, e |cffffffffDisparo Perfurador de Crânios|r$?s806345[ e |cffffffffFlecha Silvestre|r][] causam {{2}}% a mais de dano.\n\nDurante esse período, |cffffffffDisparos Perfuradores de Crânios|r$?s806345[ e |cffffffffFlecha Silvestre|r][] usados com 5 |cffffffffPontos de Arquearia|r invocam 1 |cffffffffFalcão de Guerra|r."}
T[18613]={"^Damage dealt grants the Farstrider 1 stack of Coordination%.%s*$","O dano causado concede 1 acúmulo de |cffffffffCoordenação|r ao Andarilho."}
T[18636]={"^Applies an effect to you based on the amount of stacks%. Stacks (.-) times%.\n\nAt 1 stack %- Silences you for (.-)%.\n\nAt 2 stacks %- Applies 4 stacks of Deepwood Poison to you%.\n\nAt 3 stacks %- Stuns you for (.-)%.%s*$","Aplica um efeito baseado na quantidade de acúmulos. Acumula {{1}} vezes.\n\nA 1 acúmulo - Te silencia durante {{2}}.\n\nCom 2 acúmulos - Aplica 4 acúmulos de Veneno da Mata Profunda você.\n\nCom 3 acúmulos - Te atordoa durante {{3}}."}
T[18732]={"^Reduces the cooldown of |cffffffffHunting Shot|r by (.-) sec%.%s*$","Reduz a recarga de |cffffffffTiro de Caça|r em {{1}} s."}
T[18912]={"^Causes your Wild Strike ability to Slow affected targets by (.-)%% for (.-)%.\n\nUsing Quick Shot on an enemy Slowed by this effect consumes it to Root them in place for (.-) and cause (.-) Naure Damage every (.-) sec%.\n\nAlso teaches you Wargstride, and increases all Nature Damage done by (.-)%%%.%s*$","Faz sua habilidade Golpe Selvagem reduzir a velocidade dos alvos afetados em {{1}}% durante {{2}}.\n\nUsar Disparo Rápido em um inimigo desacelerado por este efeito o consome, imobilizando o alvo durante {{3}} e causando {{4}} de dano de Natureza a cada {{5}} s.\n\nTambém ensina Marcha Loba e aumenta todo o dano de Natureza causado em {{6}}%."}
T[20943]={"^Rank 6: Highwayman\n\nHigh%-risk mode enables FFA PvP and causes you and anyone else you kill to drop loot on death%.\n\nYou gain Glory when defeating enemies within 2 ranks of your own in High%-risk, but also lose Glory on death%.%s*$","Grau 6: Salteador de Estrada\n\nO modo de alto risco habilidade JxJ FFA e Faz com que você e qualquer outra pessoa que mate descartem saque na morte.\n\nGanha Glória ao derrotar a inimigos dentro de 2 graus do seu em Alto Risco, mas também perde Glória na morte."}
T[21698]={"^Causes damage every (.-) seconds%.%s*$","Causa dano a cada {{1}} s."}
T[24993]={"^Battle prowess heightened by the song of Sylvanas%.%s*$","O canto de Sylvanas aumenta seu destreza na batalha."}
T[25047]={"^Battle prowess heightened by Jaina's powerful spell%.%s*$","O poderoso feitiço de Jaina aumenta seu destreza na batalha."}

